@Component("taxRule-handler")
@ProcessingGroup("taxRule-processing-group")
public class TaxRuleEventHandler {
	
	// core constructor
	TaxRuleEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTaxRuleEvent
     */
    @EventHandler
    public void handle( CreateTaxRuleEvent event) {
        entityManager.persist(new TaxRule(event.getTaxRuleId(), event.getName(), event.getCountry(), event.getRegion(), event.getRate(), event.getTaxInclusive(), event.getMerchant(), event.getChannels(), event.getTaxClass()));
    }

    /*
     * @param	event UpdateTaxRuleEvent
     */
    @EventHandler
    public TaxRule handle( UpdateTaxRuleEvent event) {
    	entityManager.merge(new TaxRule(event.getTaxRuleId(), event.getName(), event.getCountry(), event.getRegion(), event.getRate(), event.getTaxInclusive(), event.getMerchant(), event.getChannels(), event.getTaxClass()));
    }
    
    /*
     * @param	event DeleteTaxRuleEvent
     */
    @EventHandler
    public void on( DeleteTaxRuleEvent event) {
    	TaxRule entity = new TaxRule();
   
    	// ------------------------------------------
    	// apply the TaxRuleId
    	// ------------------------------------------
    	entity.setTaxRuleId( event.getTaxRuleId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TaxRuleRepository taxRuleEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TaxRuleEventHandler.class.getName());

}
